window.HOEREN_TESTS[73] = {"id":"auf-dem-weihnachtsmarkt","name":"Auf dem Weihnachtsmarkt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Besucher: Willkommen auf dem Weihnachtsmarkt. Heute Abend um 18 Uhr kommt der Weihnachtsmann und bringt Geschenke für die Kinder, nicht um 17 Uhr und nicht um 19 Uhr. Davor, schon um 17 Uhr, spielt ein Chor weihnachtliche Lieder. Der Glühwein-Stand ist den ganzen Tag offen. Wir wünschen eine schöne Zeit!","gender":"f","q":"Wann kommt der Weihnachtsmann?","opts":["Um 17 Uhr.","Um 19 Uhr.","Um 18 Uhr."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Treffen wir uns heute Abend auf dem Weihnachtsmarkt? Ich liebe den Glühwein dort und die gebrannten Mandeln. Bring deine Frau mit, meine kommt auch. Treffpunkt am großen Weihnachtsbaum um 19 Uhr, nicht am Glühwein-Stand und nicht am Eingang. Zieh dich warm an, es ist eiskalt! Bis später!","gender":"m","q":"Wo ist der Treffpunkt?","opts":["Am großen Weihnachtsbaum.","Am Glühwein-Stand.","Am Eingang."],"correct":0},{"transcript":"Achtung Besucher: Wegen des starken Windes bleiben heute einige Stände geschlossen. Das Karussell für die Kinder fährt aus Sicherheitsgründen nicht. Die Essensstände und Getränkestände sind aber alle offen, und der ganze Markt bleibt geöffnet. Ab morgen, wenn der Wind weg ist, läuft wieder alles normal. Vielen Dank für Ihr Verständnis!","gender":"m","q":"Was ist heute geschlossen?","opts":["Das Karussell.","Die Essensstände.","Der ganze Markt."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, ich habe auf dem Weihnachtsmarkt tolle Geschenke gefunden — handgemachte Kerzen und Schmuck, nicht Glühwein und Mandeln als Geschenk und nicht Spielzeug. Viel schöner als im Kaufhaus. Aber teuer war es auch. Wir können zusammen hingehen, du suchst doch noch etwas für deine Mutter. Ruf zurück!","gender":"f","q":"Was hat Anna gekauft?","opts":["Glühwein und Mandeln.","Kerzen und Schmuck.","Spielzeug."],"correct":1},{"transcript":"Liebe Gäste: Der Weihnachtsmarkt ist noch bis zum 23. Dezember geöffnet, danach nicht mehr. An Heiligabend bleibt alles geschlossen, und bis Neujahr ist der Markt auch nicht da. Die Öffnungszeiten sind täglich von 11 bis 21 Uhr. Am Wochenende ist immer am meisten los. Kommen Sie lieber unter der Woche, da ist es ruhiger!","gender":"f","q":"Bis wann ist der Weihnachtsmarkt geöffnet?","opts":["Bis Heiligabend.","Bis zum 23. Dezember.","Bis Neujahr."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Weihnachtsmarkt auf dem Platz macht heute um fünf auf."},{"speaker":"Lisa","gender":"f","text":"Ich habe den dicken Schal schon umgebunden. Wir sollten kurz unsere Wünsche sortieren."},{"speaker":"Lukas","gender":"m","text":"Ich trinke Glühwein am roten Stand. Die warme Tasse hilft meinen kalten Händen."},{"speaker":"Lisa","gender":"f","text":"Ich kaufe Geschenke an den kleinen Ständen. Für die Familie suche ich etwas aus Holz."},{"speaker":"Lukas","gender":"m","text":"Essen wir heute auch gebrannte Mandeln am Zuckerstand?"},{"speaker":"Lisa","gender":"f","text":"Nein. Gebrannte Mandeln essen wir nicht. Sie sind uns einfach zu süß."},{"speaker":"Lukas","gender":"m","text":"Tom kommt mit großem Hunger direkt vom Training zu uns."},{"speaker":"Lisa","gender":"f","text":"Tom isst Bratwurst am heißen Grill. Er nimmt Senf dazu und bleibt lange stehen."},{"speaker":"Lukas","gender":"m","text":"Sara bleibt ungern zwischen den lauten Buden stehen."},{"speaker":"Lisa","gender":"f","text":"Sara hört Weihnachtsmusik bei der kleinen Kapelle. Die Lieder kennt sie seit der Kindheit."},{"speaker":"Lukas","gender":"m","text":"Wollen wir heute Schlittschuh laufen auf dem Eis?"},{"speaker":"Lisa","gender":"f","text":"Nein. Schlittschuh laufen wir auch nicht. Die Fläche ist heute viel zu voll."},{"speaker":"Lukas","gender":"m","text":"Tim will sich schnell drehen und viele bunte Lichter sehen."},{"speaker":"Lisa","gender":"f","text":"Tim fährt Karussell. Er winkt von oben fröhlich zu uns herunter."},{"speaker":"Lukas","gender":"m","text":"Dann treffen wir uns pünktlich um fünf am Eingang."},{"speaker":"Lisa","gender":"f","text":"Ich bringe genug Kleingeld für die kleinen Stände mit."}],"options":[{"letter":"a","text":"Fotos machen"},{"letter":"b","text":"Den Weihnachtsbaum ansehen"},{"letter":"c","text":"Karussell fahren"},{"letter":"d","text":"Weihnachtsmusik hören"},{"letter":"e","text":"Schlittschuh laufen"},{"letter":"f","text":"Bratwurst essen"},{"letter":"g","text":"Gebrannte Mandeln essen"},{"letter":"h","text":"Glühwein trinken"},{"letter":"i","text":"Geschenke kaufen"}],"items":[{"person":"Lukas","correct":"h"},{"person":"Lisa","correct":"i"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"d"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, was kostet ein Glühwein? 4 Euro, und gibt es Pfand?"},{"speaker":"Verkäuferin","gender":"f","text":"4 Euro, plus 3 Euro Pfand für die Tasse. Ohne Pfand geht es nicht."},{"speaker":"Kunde","gender":"m","text":"Bekomme ich das Pfand zurück, die 3 Euro?"},{"speaker":"Verkäuferin","gender":"f","text":"Ja, wenn Sie die Tasse zurückbringen, bekommen Sie die 3 Euro Pfand zurück."},{"speaker":"Kunde","gender":"m","text":"Gut, dann zahle ich 4 Euro plus 3 Euro Pfand. Danke."}],"q":"Wie viel Pfand zahlt man für die Tasse?","opts":["4 Euro.","Kein Pfand.","3 Euro."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, sind die Kerzen handgemacht? Was kostet die große, 6 Euro oder 18 Euro?"},{"speaker":"Händler","gender":"m","text":"Ja, alle selbst gemacht. Nicht 6 und nicht 18 für die große."},{"speaker":"Frau","gender":"f","text":"Was kostet die große Kerze?"},{"speaker":"Händler","gender":"m","text":"12 Euro, die kleine 6 Euro. Die große ist 12, nicht 18."},{"speaker":"Frau","gender":"f","text":"Dann nehme ich die große für 12 Euro. Danke schön."}],"q":"Was kostet die große Kerze?","opts":["6 Euro.","18 Euro.","12 Euro."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Möchtest du Mandeln oder Lebkuchen mit Schokolade? Glühwein gibt es für dich nicht."},{"speaker":"Tochter","gender":"f","text":"Lebkuchen, bitte, keine Mandeln!"},{"speaker":"Vater","gender":"m","text":"Mit Schokolade oder ohne?"},{"speaker":"Tochter","gender":"f","text":"Ja, Lebkuchen mit Schokolade, bitte. Mandeln will ich nicht."},{"speaker":"Vater","gender":"m","text":"Gut, dann nimmst du Lebkuchen mit Schokolade. Glühwein trinke ich allein, das ist okay. Danke."}],"q":"Was möchte die Tochter?","opts":["Lebkuchen mit Schokolade.","Mandeln.","Glühwein."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, wo ist die Eisbahn? Kann man Schlittschuhe leihen, oder sind sie kostenlos?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Hinter dem großen Baum. Kostenlos sind sie nicht."},{"speaker":"Mann","gender":"m","text":"Kann man Schlittschuhe leihen, und was kostet das, 3 Euro?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, leihen für 5 Euro, nicht 3 Euro und nicht kostenlos."},{"speaker":"Mann","gender":"m","text":"Gut, dann leihe ich Schlittschuhe für 5 Euro. Danke."}],"q":"Was kostet das Leihen der Schlittschuhe?","opts":["5 Euro.","3 Euro.","Kostenlos."],"correct":0},{"lines":[{"speaker":"Besucherin","gender":"f","text":"Guten Tag, wann beginnt das Konzert? Kostet das 10 Euro oder 5 Euro?"},{"speaker":"Mann","gender":"m","text":"Um 20 Uhr auf der großen Bühne. 10 Euro und 5 Euro sind falsch."},{"speaker":"Besucherin","gender":"f","text":"Kostet das Konzert etwas, 10 Euro oder 5 Euro?"},{"speaker":"Mann","gender":"m","text":"Nein, es ist kostenlos. Keine 10 Euro und keine 5 Euro."},{"speaker":"Besucherin","gender":"f","text":"Wunderbar, kostenlos um 20 Uhr. Danke für die Info."}],"q":"Was kostet das Konzert?","opts":["10 Euro.","Es ist kostenlos.","5 Euro."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Brandt, einem Standbesitzer auf dem Weihnachtsmarkt. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Brandt, Sie haben seit 20 Jahren einen Stand auf dem Weihnachtsmarkt. Was verkaufen Sie?"},{"speaker":"Brandt","gender":"m","text":"Holzspielzeug und Weihnachtsschmuck, alles selbst gemacht. In meiner Werkstatt arbeite ich das ganze Jahr dafür. Der Weihnachtsmarkt ist für mich die wichtigste Zeit — hier verkaufe ich fast alles, was ich in zwölf Monaten gebaut habe. Es ist mein ganzes Leben."},{"speaker":"Reporterin","gender":"f","text":"Wie sind die langen Tage in der Kälte?"},{"speaker":"Brandt","gender":"m","text":"Anstrengend, ehrlich gesagt. Von morgens bis abends draußen, oft bei Minusgraden. Die Füße werden eiskalt. Aber die Stimmung entschädigt für alles. Die Leute sind fröhlich, es riecht nach Glühwein und Zimt. Diese Atmosphäre gibt es nur einmal im Jahr."},{"speaker":"Reporterin","gender":"f","text":"Hat sich der Weihnachtsmarkt verändert?"},{"speaker":"Brandt","gender":"m","text":"Ja, leider nicht nur zum Guten. Es gibt immer mehr billige Massenware aus dem Ausland. Echtes Handwerk wird seltener. Viele Stände verkaufen nur noch Essen und Getränke. Dabei lebt ein guter Weihnachtsmarkt von den kleinen, besonderen Sachen. Das vermisse ich manchmal."},{"speaker":"Reporterin","gender":"f","text":"Was ist Ihr schönstes Erlebnis?"},{"speaker":"Brandt","gender":"m","text":"Wenn Kinder vor meinem Stand stehen und staunen. Manche, die früher bei mir gekauft haben, kommen jetzt mit ihren eigenen Kindern. Eine Familie kommt seit fünfzehn Jahren jedes Jahr. Solche Momente machen mich glücklich. Das ist mehr wert als jedes Geld."},{"speaker":"Reporterin","gender":"f","text":"Was wünschen Sie sich für die Zukunft?"},{"speaker":"Brandt","gender":"m","text":"Dass die Menschen wieder mehr Wert auf echtes Handwerk legen. Ein handgemachtes Geschenk hat eine Seele, ein billiges aus der Fabrik nicht. Und ich wünsche mir junge Handwerker, die das weitermachen. Sonst stirbt diese schöne Tradition langsam aus. Das wäre sehr schade."}],"items":[{"q":"Herr Brandt verkauft selbst gemachtes Holzspielzeug.","correct":"ja"},{"q":"Er findet die Arbeit in der Kälte überhaupt nicht anstrengend.","correct":"nein"},{"q":"Er meint, es gibt immer mehr billige Massenware.","correct":"ja"},{"q":"Manche Familien kommen seit vielen Jahren zu seinem Stand.","correct":"ja"},{"q":"Er wünscht sich, dass das Handwerk verschwindet.","correct":"nein"}]}]};
